"""Read local configuration without executing shell text or logging secrets."""

from __future__ import annotations

import os
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[2]
SERVICES = {
    "user-service": ("user_db", 8081),
    "capability-service": ("capability_db", 8082),
    "billing-service": ("billing_db", 8083),
    "ai-chat-service": ("ai_chat_db", 8090),
}


def read_env(path: Path) -> dict[str, str]:
    """Read the simple KEY=value files generated by this project."""
    if not path.exists():
        return {}
    values: dict[str, str] = {}
    for line in path.read_text(encoding="utf-8-sig").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, separator, value = line.partition("=")
        if not separator or not key.strip().replace("_", "").isalnum():
            raise ValueError(f"Invalid configuration line in {path.name}")
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            value = value[1:-1]
        values[key.strip()] = value
    return values


def service_python(service_root: Path) -> Path:
    directory = "Scripts" if os.name == "nt" else "bin"
    executable = "python.exe" if os.name == "nt" else "python"
    return service_root / ".venv" / directory / executable


def component_environment(root: Path) -> dict[str, str]:
    """Explicit command environment wins over the local shared config file."""
    return {**read_env(root / ".env"), **os.environ}
